package com.mcphone.server;

import android.app.Activity;
import android.app.AlertDialog;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import java.io.*;
import java.util.*;

public class ConfigActivity extends Activity {
    private static final long MAX_BYTES=1024L*1024L;
    private static final String[] EXT={".properties",".yml",".yaml",".json",".txt",".conf",".toml",".cfg",".xml",".mcmeta"};
    private String serverId, editingPath; private File serverDir; private LinearLayout root; private EditText editor; private TextView message;
    @Override protected void onCreate(Bundle b){super.onCreate(b);Ui.applyTheme(this);Ui.applySystemBars(this);Dirs.init(this);serverId=ServerProfiles.safeId(getIntent().getStringExtra("server_id"));serverDir=Dirs.server(this,serverId);if(!serverDir.exists())serverDir.mkdirs();ensureProps();showList();}
    private void newRoot(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,20),Ui.dp(this,20),Ui.dp(this,20),Ui.dp(this,16));root.setBackgroundColor(Ui.BG);root.setFitsSystemWindows(true);setContentView(root);}
    private void heading(String tag,String title){root.addView(Ui.text(this,tag,12,Ui.ACCENT));TextView t=Ui.text(this,title,25,Ui.TEXT);t.setTypeface(Ui.font(this),android.graphics.Typeface.BOLD);root.addView(t,Ui.row(this,4));}
    private void showList(){editingPath=null;editor=null;newRoot();heading("$ config list",ServerProfiles.name(this,serverId));root.addView(Ui.text(this,"Wähle eine Config-Datei zum Anzeigen oder Bearbeiten.",13,Ui.DIM),Ui.row(this,4));ScrollView sc=new ScrollView(this);LinearLayout items=new LinearLayout(this);items.setOrientation(LinearLayout.VERTICAL);sc.addView(items,new ScrollView.LayoutParams(-1,-2));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,0,1);lp.topMargin=Ui.dp(this,14);root.addView(sc,lp);List<File> files=new ArrayList<>();collect(serverDir,files,0);Collections.sort(files,(a,b)->relative(a).compareToIgnoreCase(relative(b)));for(File f:files){String path=relative(f);LinearLayout card=Ui.card(this);card.addView(Ui.text(this,path,14,Ui.TEXT));TextView btn=Ui.button(this,"Bearbeiten",false);btn.setOnClickListener(v->showEditor(path));card.addView(btn,Ui.row(this,8));items.addView(card,Ui.row(this,8));}TextView create=Ui.button(this,"+  Config-Datei erstellen",true);create.setOnClickListener(v->createFileDialog());root.addView(create,Ui.row(this,10));TextView back=Ui.button(this,"Zurück zur Serverliste",false);back.setOnClickListener(v->finish());root.addView(back,Ui.row(this,8));}
    private void showEditor(String rel){try{File f=safeFile(rel);if(!f.exists()||!f.isFile())throw new IOException("Datei nicht gefunden.");if(f.length()>MAX_BYTES)throw new IOException("Datei ist größer als 1 MB.");editingPath=relative(f);String content=read(f);newRoot();heading("$ config edit",editingPath);ScrollView sc=new ScrollView(this);editor=new EditText(this);editor.setText(content);editor.setTextColor(Ui.TEXT);editor.setHintTextColor(Ui.DIM);editor.setTypeface(Ui.font(this));editor.setTextSize(13);editor.setGravity(Gravity.TOP|Gravity.START);editor.setSingleLine(false);editor.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);editor.setBackground(Ui.box(this,Ui.CARD,Ui.STROKE,14));editor.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14));sc.addView(editor,new ScrollView.LayoutParams(-1,-2));LinearLayout.LayoutParams el=new LinearLayout.LayoutParams(-1,0,1);el.topMargin=Ui.dp(this,14);root.addView(sc,el);message=Ui.text(this,"Änderungen gelten je nach Datei beim nächsten Neustart.",12,Ui.DIM);root.addView(message,Ui.row(this,8));TextView save=Ui.button(this,"Änderungen speichern",true);save.setOnClickListener(v->save());root.addView(save,Ui.row(this,10));TextView back=Ui.button(this,"Dateiliste",false);back.setOnClickListener(v->showList());root.addView(back,Ui.row(this,8));}catch(Exception e){Ui.dialog(this).setMessage(e.getMessage()).setPositiveButton("OK",null).show();}}
    private void save(){if(editor==null||editingPath==null)return;String content=editor.getText().toString();if(content.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>MAX_BYTES){message.setText("Datei ist größer als 1 MB.");message.setTextColor(Ui.ERR);return;}try{File f=safeFile(editingPath);File parent=f.getParentFile();if(parent!=null&&!parent.exists()&&!parent.mkdirs())throw new IOException("Ordner konnte nicht erstellt werden.");try(Writer w=new OutputStreamWriter(new FileOutputStream(f),"UTF-8")){w.write(content);}Ui.dialog(this).setMessage("Datei gespeichert: "+editingPath).setPositiveButton("OK",(d,w)->showList()).show();}catch(Exception e){message.setText("Speichern fehlgeschlagen: "+e.getMessage());message.setTextColor(Ui.ERR);}}
    private void createFileDialog(){EditText input=Ui.input(this,"","plugins/Beispiel/config.yml",false);input.setSingleLine(true);input.setBackground(Ui.box(this,Ui.FIELD,Ui.STROKE,16));LinearLayout wrap=new LinearLayout(this);wrap.setPadding(Ui.dp(this,5),Ui.dp(this,4),Ui.dp(this,5),Ui.dp(this,4));wrap.setBackground(Ui.box(this,Ui.CARD,Ui.STROKE,18));wrap.addView(input,new LinearLayout.LayoutParams(-1,-2));Ui.dialog(this).setTitle(L.t(this,"Config-Datei erstellen")).setView(wrap).setNegativeButton(L.t(this,"Abbrechen"),null).setPositiveButton("Erstellen",(d,w)->{try{File f=safeFile(input.getText().toString().trim());if(f.exists())throw new IOException("Datei existiert bereits.");File par=f.getParentFile();if(par!=null&&!par.exists()&&!par.mkdirs())throw new IOException("Ordner konnte nicht erstellt werden.");if(!f.createNewFile())throw new IOException("Datei konnte nicht angelegt werden.");showEditor(input.getText().toString().trim());}catch(Exception e){Ui.dialog(this).setMessage("Datei konnte nicht erstellt werden: "+e.getMessage()).setPositiveButton("OK",null).show();}}).show();}
    private void collect(File dir,List<File> out,int depth){if(depth>5)return;File[] fs=dir.listFiles();if(fs==null)return;for(File f:fs){if(f.isDirectory())collect(f,out,depth+1);else if(f.isFile()&&isConfig(f.getName())&&f.length()<=MAX_BYTES)out.add(f);}}
    private boolean isConfig(String n){String s=n.toLowerCase(Locale.ROOT);for(String e:EXT)if(s.endsWith(e))return true;return false;}
    private File safeFile(String rel)throws IOException{if(rel==null||rel.trim().isEmpty())throw new IOException("Dateipfad fehlt.");File f=new File(serverDir,rel.trim());String base=serverDir.getCanonicalPath()+File.separator;if(!f.getCanonicalPath().startsWith(base))throw new IOException("Pfad außerhalb des Serverordners ist nicht erlaubt.");if(!isConfig(f.getName()))throw new IOException("Nur unterstützte Text-Configs sind erlaubt.");return f;}
    private String relative(File f){return serverDir.toURI().relativize(f.toURI()).getPath();}
    private String read(File f)throws IOException{StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),"UTF-8"))){String line;while((line=r.readLine())!=null)b.append(line).append('\n');}return b.toString();}
    private void ensureProps(){File f=new File(serverDir,"server.properties");Prefs p=new Prefs(this,serverId);if(f.exists()||!p.b("setup",false))return;try(Writer w=new OutputStreamWriter(new FileOutputStream(f),"UTF-8")){w.write("server-port="+p.i("port",25565)+"\nmax-players="+p.i("maxPlayers",10)+"\ndifficulty="+p.s("difficulty","normal")+"\nmotd="+p.s("motd","Minecraft Server")+"\n");}catch(Exception ignored){}}
    @Override public void onBackPressed(){if(editingPath!=null)showList();else super.onBackPressed();}
}
